export class WeightedConfidenceResolver {
  constructor() {
    this.agentConfidenceScores = {};
    this.agentReliabilityScores = {};
  }

  setConfidenceScore(agentId, confidence) {
    this.agentConfidenceScores[agentId] = confidence;
  }

  setReliabilityScore(agentId, reliability) {
    this.agentReliabilityScores[agentId] = reliability;
  }

  resolveDecisions(agentOutputs) {
    return agentOutputs.reduce((bestOutput, currentOutput) => {
      const agentId = currentOutput.agentId;
      const weightedScore = (this.agentConfidenceScores[agentId] || 0) * (this.agentReliabilityScores[agentId] || 0);
      if (!bestOutput || weightedScore > bestOutput.weightedScore) {
        return { ...currentOutput, weightedScore };
      }
      return bestOutput;
    }, null);
  }
}

export default WeightedConfidenceResolver;